def search_triples(max_val, n_range):
    results = {}
    for n in n_range:
        results[n] = []
        for a in range(1, max_val):
            for b in range(a + 1, max_val):
                # Equation: (a+b+c)(ab+bc+ca+1) = 4n*a*b*c
                # Let's solve for c.
                # (a+b+c)(ab + c(a+b) + 1) = 4n*abc
                # (a+b)(ab+1) + (a+b)*c(a+b) + c(ab+1) + c*c(a+b) = 4n*abc
                # (a+b)(ab+1) + c((a+b)^2 + ab+1) + c^2(a+b) = 4n*abc
                # (a+b)c^2 + ((a+b)^2 + ab+1 - 4nab)c + (a+b)(ab+1) = 0

                # Quadratic in c: Ac^2 + Bc + C = 0
                A_coeff = a + b
                B_coeff = (a + b)**2 + a*b + 1 - 4*n*a*b
                C_coeff = (a + b) * (a*b + 1)

                delta = B_coeff**2 - 4*A_coeff*C_coeff
                if delta >= 0:
                    sqrt_delta = int(delta**0.5)
                    if sqrt_delta * sqrt_delta == delta:
                        for sign in [-1, 1]:
                            num = -B_coeff + sign * sqrt_delta
                            den = 2 * A_coeff
                            if num % den == 0:
                                c = num // den
                                if c > b: # Ensure distinct and a < b < c
                                    results[n].append((a, b, c))
    return results

results = search_triples(200, range(1, 8))
for n, triples in results.items():
    print(f"n={n}: {triples}")
